  background: var(--ix-accent);
  border-color: var(--ix-accent);
}
.ix-root .ix-btn--primary:hover { opacity: 0.88; }
.ix-root .ix-btn:disabled { opacity: 0.5; cursor: default; }

/* ---------- 判定结果条 ---------- */
.ix-root .ix-verdict {
  margin-top: 14px;
  padding: 10px 14px;
  font-size: 14.5px;
  font-weight: 600;
  border: 1.5px solid var(--ix-line);
  border-radius: 10px;
