/* ---------- 排序 / 配对 共用的“卡片”基底 ---------- */
.ix-root .ix-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.ix-root .ix-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 11px 13px;
  background: var(--ix-surface);
  border: 1.5px solid var(--ix-line);
  border-radius: 10px;
  cursor: grab;
  /* touch-action:none 让移动端拖拽时不触发页面滚动——
     否则手指一移动页面就跟着滚，元素永远追不上手指。 */
  touch-action: none;
  -webkit-user-select: none;
  user-select: none;
  transition: border-color 0.15s, background 0.15s, opacity 0.15s, transform 0.22s cubic-bezier(0.2, 0, 0, 1), box-shadow 0.2s;
  will-change: transform;
}
.ix-root .ix-grip {
  flex: 0 0 auto;
  font-size: 13px;
  letter-spacing: -2px;
  color: var(--ix-muted);
}
.ix-root .ix-num {
  flex: 0 0 auto;
  min-width: 18px;
  font-size: 12px;
  font-weight: 700;
  color: var(--ix-muted);
}
.ix-root .ix-txt { flex: 1; min-width: 0; }
.ix-root .ix-item.is-dragging {
  opacity: 0.96;
  cursor: grabbing;
  border-color: var(--ix-accent);
  background: var(--ix-surface);
  box-shadow: 0 12px 28px rgba(0, 0, 0, 0.18);
  transform: scale(1.025);
  z-index: 10;
  transition: none;
}
.ix-root .ix-item.is-sel { border-color: var(--ix-accent); background: var(--ix-accent-soft); }
.ix-root .ix-item.is-correct { border-color: var(--ix-ok); background: var(--ix-ok-soft); }
.ix-root .ix-item.is-wrong { border-color: var(--ix-bad); background: var(--ix-bad-soft); }
.ix-root.is-locked .ix-item { cursor: default; }

