  text-transform: uppercase;
  color: var(--muted);
}
.card .de-badges {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 12px;
}
.card .de-star { color: #e0a92b; letter-spacing: 1px; font-size: 14px; }
.card .de-oxford {
  font-size: 11px;
  font-weight: 600;
