.ix-root .ix-blank:focus { background: var(--ix-accent-soft); }
.ix-root .ix-blank.is-correct { border-bottom-color: var(--ix-ok); color: var(--ix-ok); font-weight: 600; }
.ix-root .ix-blank.is-wrong { border-bottom-color: var(--ix-bad); color: var(--ix-bad); }
.ix-root .ix-blank.is-near { border-bottom-color: var(--ix-near); color: var(--ix-near); }
.ix-root .ix-blank.is-empty { border-bottom-style: dashed; }
/* 揭示态：把挖空换成正确答案（绿色下划线），与用户输入形成对照 */
.ix-root .ix-reveal {
  padding: 0 6px;
  font-weight: 700;
  color: var(--ix-ok);
  border-bottom: 2px solid var(--ix-ok);
}

/* ---------- 排序 / 配对 共用的“卡片”基底 ---------- */
.ix-root .ix-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.ix-root .ix-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 11px 13px;
  background: var(--ix-surface);
  border: 1.5px solid var(--ix-line);
  border-radius: 10px;
  cursor: grab;
  /* touch-action:none 让移动端拖拽时不触发页面滚动——
     否则手指一移动页面就跟着滚，元素永远追不上手指。 */
  touch-action: none;
  -webkit-user-select: none;
  user-select: none;
  transition: border-color 0.15s, background 0.15s, opacity 0.15s, transform 0.22s cubic-bezier(0.2, 0, 0, 1), box-shadow 0.2s;
  will-change: transform;
}
.ix-root .ix-grip {
  flex: 0 0 auto;
  font-size: 13px;
  letter-spacing: -2px;
  color: var(--ix-muted);
}
.ix-root .ix-num {
  flex: 0 0 auto;
  min-width: 18px;
  font-size: 12px;
  font-weight: 700;
  color: var(--ix-muted);
}
.ix-root .ix-txt { flex: 1; min-width: 0; }
.ix-root .ix-item.is-dragging {
  opacity: 0.96;
  cursor: grabbing;
  border-color: var(--ix-accent);
  background: var(--ix-surface);
  box-shadow: 0 12px 28px rgba(0, 0, 0, 0.18);
  transform: scale(1.025);
  z-index: 10;
  transition: none;
}
.ix-root .ix-item.is-sel { border-color: var(--ix-accent); background: var(--ix-accent-soft); }
.ix-root .ix-item.is-correct { border-color: var(--ix-ok); background: var(--ix-ok-soft); }
.ix-root .ix-item.is-wrong { border-color: var(--ix-bad); background: var(--ix-bad-soft); }
.ix-root.is-locked .ix-item { cursor: default; }

/* ---------- 配对 ---------- */
.ix-root .ix-cols {
  display: flex;
  gap: 12px;
  align-items: flex-start;
}
.ix-root .ix-col {
  flex: 1 1 0;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.ix-root .ix-card {
  position: relative;
  padding: 10px 12px;
  font: inherit;
  line-height: 1.55;
  color: inherit;
  text-align: left;
  background: var(--ix-surface);
  border: 1.5px solid var(--ix-line);
  border-radius: 10px;
  cursor: pointer;
  -webkit-appearance: none;
  appearance: none;
  transition: border-color 0.15s, background 0.15s;
}
.ix-root .ix-card:hover { border-color: var(--ix-accent); }
.ix-root .ix-card.is-sel { border-color: var(--ix-accent); background: var(--ix-accent-soft); }
/* 已配对的角标：左右两侧同一个数字 = 同一组，这是配对的唯一视觉表达 */
.ix-root .ix-card.is-linked::after {
  content: attr(data-badge);
  position: absolute;
  top: -7px;
  right: -7px;
  width: 19px;
  height: 19px;
  line-height: 19px;
  text-align: center;
  font-size: 11px;
  font-weight: 700;
  color: #fff;
  background: var(--ix-accent);
  border-radius: 50%;
}
.ix-root .ix-card.is-correct { border-color: var(--ix-ok); background: var(--ix-ok-soft); }
.ix-root .ix-card.is-correct::after { background: var(--ix-ok); }
.ix-root .ix-card.is-wrong { border-color: var(--ix-bad); background: var(--ix-bad-soft); }
.ix-root .ix-card.is-wrong::after { background: var(--ix-bad); }
.ix-root.is-locked .ix-card { cursor: default; }
.ix-root.is-locked .ix-card:hover { border-color: var(--ix-line); }

/* ---------- 操作条 / 按钮 ---------- */
.ix-root .ix-bar {
  display: flex;
  flex-wrap: wrap;
  gap: 9px;
  margin-top: 16px;
}
.ix-root .ix-btn {
  padding: 8px 16px;
  font: inherit;
  font-size: 14.5px;
  font-weight: 600;
  color: inherit;
  background: var(--ix-surface);
  border: 1.5px solid var(--ix-line);
  border-radius: 9px;
  cursor: pointer;
  -webkit-appearance: none;
  appearance: none;
  transition: border-color 0.15s, background 0.15s, opacity 0.15s;
}
.ix-root .ix-btn:hover { border-color: var(--ix-accent); }
.ix-root .ix-btn--primary {
  color: #fff;
  background: var(--ix-accent);
  border-color: var(--ix-accent);
}
.ix-root .ix-btn--primary:hover { opacity: 0.88; }
.ix-root .ix-btn:disabled { opacity: 0.5; cursor: default; }

/* ---------- 判定结果条 ---------- */
.ix-root .ix-verdict {
  margin-top: 14px;
  padding: 10px 14px;
  font-size: 14.5px;
  font-weight: 600;
  border: 1.5px solid var(--ix-line);
  border-radius: 10px;
}
.ix-root .ix-verdict.is-ok { color: var(--ix-ok); background: var(--ix-ok-soft); border-color: var(--ix-ok); }
.ix-root .ix-verdict.is-bad { color: var(--ix-bad); background: var(--ix-bad-soft); border-color: var(--ix-bad); }
.ix-root .ix-verdict.is-near { color: var(--ix-near); background: var(--ix-near-soft); border-color: var(--ix-near); }
.ix-root .ix-verdict.is-info { color: var(--ix-muted); }
.ix-root .ix-verdict .ix-sub {
  display: block;
  margin-top: 4px;
  font-size: 13px;
  font-weight: 400;
  line-height: 1.6;
  opacity: 0.9;
  white-space: pre-wrap;
}

/* ---------- 站内预览容器里的微调（不影响 Anki） ---------- */
/* .card-face 里已经有较大的内边距，交互元素再撑一圈就太松了 */
.card-face .ix-root .ix-q { margin-bottom: 14px; }
.card-face .ix-root .ix-bar { margin-top: 14px; }
